SRC=srcs([('https://docs.gitlab.com/user/project/merge_requests/','GitLab Docs – Merge requests'),('https://docs.gitlab.com/user/project/repository/branches/protected/','GitLab Docs – Protected branches'),('https://docs.gitlab.com/user/project/merge_requests/approvals/','GitLab Docs – Merge request approvals'),('https://docs.gitlab.com/user/project/issues/managing_issues/','GitLab Docs – Managing issues (closing patterns)'),GD('gitworkflows','Git – gitworkflows'),GD('git-push')])
def dia(vi):
    t=('Đường đi của một tính năng từ máy bạn tới main' if vi else 'A feature\'s path from your machine to main','Sơ đồ do Vinc Academy biên soạn.' if vi else 'Diagram by Vinc Academy.','dg-%s-g05'%('vi' if vi else 'en'))
    items=[(4,(['Máy bạn'],['Your machine']),('nhánh + commit','branch + commits'),False),(170,(['Merge request'],['Merge request']),('mô tả, reviewer','text, reviewers'),True),(336,(['Review và CI'],['Review and CI']),('thread, approve','threads, approvals'),False),(502,(['Nhánh main'],['main branch']),('đã bảo vệ','protected'),False)]
    b=''
    for x,ti,su,ac in items:
        b+='<rect class="%s" x="%d" y="45" width="134" height="80" rx="12" />\n'%('dg-accent' if ac else 'dg-box',x)
        for i,l in enumerate(ti[0 if vi else 1]): b+='<text class="dg-title" x="%d" y="%d">%s</text>\n'%(x+14,68+i*18,l)
        b+='<text class="dg-text" x="%d" y="115">%s</text>\n'%(x+14,su[0 if vi else 1])
    for x,l in [(138,'git push'),(304,'reviewer'),(470,'merge')]:
        b+='<path class="dg-arrow" d="M%d 85 h22 m-8 -6 l8 6 l-8 6" /><text class="dg-text" text-anchor="middle" x="%d" y="34">%s</text>\n'%(x,x+14,l)
    b+='<text class="dg-text" x="4" y="150">%s</text>\n'%('Nhánh chính được bảo vệ: thay đổi chỉ vào qua merge request đã qua review.' if vi else 'The main branch is protected: changes only get in through a reviewed merge request.')
    return fig('640 162',t[0],b,t[1],t[2])
MR_TPL='''## Mục đích
Thêm trường học phí cho khóa học để bộ phận kinh doanh báo giá.

## Thay đổi
- models/course.py: thêm trường price (Float)
- views/course_views.xml: hiển thị price trên form và list

## Cách kiểm tra
1. Nâng cấp module: odoo-bin -u vinc_course -d vinc_test
2. Mở Khóa học, nhập học phí, lưu

Closes #12'''
MR_TPL_EN='''## Purpose
Add a price field to courses so sales can quote.

## Changes
- models/course.py: add the price field (Float)
- views/course_views.xml: show price on the form and list views

## How to test
1. Upgrade the module: odoo-bin -u vinc_course -d vinc_test
2. Open Courses, enter a price, save

Closes #12'''
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a05');base(sb);remote_setup(sb)
    sb.q('git remote add origin git@gitlab.example.com:vinc/vinc_course.git;git push -q -u origin main 2>&1')
    sb.q('cd .. && git clone -q git@gitlab.example.com:vinc/vinc_course.git vinc_course_binh && cd vinc_course_binh && git config user.name "Trần Thị Bình" && git config user.email "binh.tran@example.com"')
    T1=sb.P('git switch main','git pull','git switch -c 12-course-price',"echo \"    price = fields.Float(string='Học phí')\" >> models/course.py",'git commit -am "[IMP] vinc_course: thêm trường học phí" -m "Closes #12"','git push -u origin 12-course-price','git log -1 --format=%B')
    T2=sb.P('sed -i "s/Học phí/Học phí (VND)/" models/course.py','git commit -am "[IMP] vinc_course: ghi rõ đơn vị học phí theo review"','git push','git log --oneline origin/main..HEAD')
    T3=sb.P('# GitLab thực hiện bước này khi bấm Merge; ở đây Bình giả lập bằng lệnh','cd ../vinc_course_binh','git fetch','git switch main','git merge --no-ff origin/12-course-price -m "Merge branch \'12-course-price\' into \'main\'"','git push','git push origin --delete 12-course-price')
    T4=sb.P('cd ../vinc_course','git switch main','git pull','git log --oneline --graph -n 4','git branch -d 12-course-price','git fetch --prune')
    hook=sb.root+'/gitlab/vinc/vinc_course.git/hooks/pre-receive'
    os.makedirs(os.path.dirname(hook),exist_ok=True) if False else None
    open(sb.home+'/gitlab/vinc/vinc_course.git/hooks/pre-receive','w').write('#!/bin/sh\nwhile read old new ref; do\n  if [ "$ref" = refs/heads/main ]; then echo "Nhánh main được bảo vệ: hãy push nhánh riêng và mở merge request." >&2; exit 1; fi\ndone\n');os.chmod(sb.home+'/gitlab/vinc/vinc_course.git/hooks/pre-receive',0o755)
    T5=sb.P('echo "# thử đẩy thẳng" >> README.md','git add README.md','git commit -m "[ADD] vinc_course: README"','git push')
    T5b=sb.P('git switch -c fix/readme','git push -u origin fix/readme','git switch main','git reset --hard origin/main','git status -sb')
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Merge request (MR) là nơi cả nhóm xem, bàn luận và duyệt thay đổi trước khi nó vào nhánh chính.</strong> Bài này đi trọn một vòng trên GitLab với module <code>vinc_course</code>: tạo nhánh theo issue, push, mở MR với mô tả tốt và <code>Closes #12</code>, sửa theo góp ý của reviewer bằng cách push thêm commit, merge, dọn nhánh, và hiểu vì sao <code>main</code> thường bị bảo vệ không cho push thẳng. Các lệnh chạy thật trên repo giả lập; phần thao tác giao diện lấy theo tài liệu GitLab.','<strong>A merge request (MR) is where the team looks at, discusses and approves a change before it reaches the main branch.</strong> This part walks a full cycle on GitLab with the <code>vinc_course</code> module: a branch named after an issue, push, an MR with a good description and <code>Closes #12</code>, fixing reviewer feedback by pushing more commits, merge, cleanup, and why <code>main</code> is usually protected against direct pushes. The commands run for real on a simulated repo; the interface steps follow GitLab\'s documentation.')))
    o+=h2('mr-la-gi',t('Merge request là gì và vì sao doanh nghiệp bắt buộc dùng','What a merge request is and why companies insist on it'))
    o+=p(t('Ở bài 3 bạn tự gõ <code>git merge</code> trên máy mình. Làm vậy trong nhóm sẽ có rủi ro: code chưa ai xem đã vào nhánh chính, và nếu hỏng thì cả nhóm cùng chịu. Merge request giải quyết bằng một bước chặn ở giữa. Theo tài liệu GitLab, MR là nơi tập trung để nhóm review code, thảo luận và theo dõi thay đổi; trong một MR bạn thấy mô tả, các thay đổi code kèm góp ý ngay tại dòng, thông tin pipeline CI/CD, báo cáo khả năng merge, bình luận và danh sách commit.','In part 3 you ran <code>git merge</code> yourself on your own machine. In a team that is risky: code nobody has seen lands in the main branch and, if it breaks, everyone pays. A merge request adds a gate in the middle. According to GitLab\'s documentation, an MR is a central place for the team to review code, discuss and track changes; inside one you see the description, the code changes with comments on the exact lines, CI/CD pipeline information, mergeability reports, comments and the list of commits.'))
    o+=dia(vi)
    o+=p(t('Một MR có hai vai: <strong>assignee</strong> (người sở hữu, thường là tác giả, chịu trách nhiệm tiến độ) và <strong>reviewer</strong> (người xem code, góp ý, và nếu đủ điều kiện thì approve). GitLab gọi tính năng này là <em>merge request</em>; GitHub gọi là <em>pull request</em>, nhưng quy trình gần như giống hệt.','An MR has two roles: the <strong>assignee</strong> (the owner, usually the author, responsible for progress) and the <strong>reviewer</strong> (who reads the code, comments and, if eligible, approves). GitLab calls it a <em>merge request</em>; GitHub calls it a <em>pull request</em>, but the workflow is practically the same.'))
    o+=h2('quy-trinh',t('Một vòng đầy đủ: từ issue đến main','A full cycle: from issue to main'))
    o+=p(t('Giả sử issue #12 trên GitLab yêu cầu “thêm học phí cho khóa học”. Bước đầu là chắc chắn bạn bắt đầu từ <code>main</code> mới nhất, rồi tạo nhánh. Tài liệu GitLab cho biết nhánh có tiền tố là mã issue (ví dụ <code>12-course-price</code>) giúp GitLab điền sẵn tiêu đề và liên kết issue khi mở MR. Dòng thứ hai của commit (<code>-m</code> lần hai) ghi <code>Closes #12</code> để issue tự đóng khi MR được merge:','Suppose issue #12 in GitLab asks to “add a price to courses”. First make sure you start from the latest <code>main</code>, then create the branch. GitLab\'s documentation notes that a branch prefixed with the issue number (such as <code>12-course-price</code>) lets GitLab prefill the title and link the issue when you open the MR. The second message paragraph (a second <code>-m</code>) says <code>Closes #12</code> so the issue closes itself once the MR lands:'))
    o+=T1
    o+=p(t('Sau khi push, mở GitLab, vào <em>Code → Merge requests</em> và chọn tạo MR mới cho nhánh vừa đẩy (nhiều bản GitLab còn hiện sẵn nút gợi ý ngay trên trang dự án). Điền tiêu đề, mô tả, chọn assignee là bạn và một hoặc hai reviewer; tick <em>Delete source branch when merge request accepted</em> để nhánh nguồn tự xóa sau khi merge. Phần mô tả là chỗ đáng đầu tư nhất, ví dụ:','After pushing, open GitLab, go to <em>Code → Merge requests</em> and create a new MR for the branch you just pushed (many GitLab versions also show a suggestion button on the project page). Fill in the title and description, set yourself as assignee and pick one or two reviewers; tick <em>Delete source branch when merge request accepted</em> so the source branch removes itself after the merge. The description is the part worth investing in, for example:'))
    o+=pre(MR_TPL if vi else MR_TPL_EN)
    o+=p(t('Reviewer sẽ để lại góp ý trên từng dòng. Theo tài liệu, các <em>thread</em> chưa resolve sẽ chặn việc merge, còn bình luận đơn thì không. Để sửa theo góp ý, bạn <strong>không</strong> tạo MR mới: chỉ cần commit và push thêm lên cùng nhánh, MR tự cập nhật. Lệnh <code>git log origin/main..HEAD</code> liệt kê đúng những commit mà MR đang chứa:','The reviewer leaves comments on individual lines. According to the documentation, <em>threads</em> that are still open hold up the merge, single comments do not. To act on feedback you do <strong>not</strong> create a new MR: commit and push more to the same branch and the MR updates itself. The command <code>git log origin/main..HEAD</code> lists exactly the commits the MR contains:'))
    o+=T2
    o+=p(t('Khi reviewer hài lòng và pipeline xanh, một người có quyền bấm <strong>Merge</strong>. Quy tắc mặc định theo tài liệu: nhánh mặc định (thường là <code>main</code>) được bảo vệ, chỉ Maintainer trở lên được merge vào đó; Developer merge được MR nhắm vào nhánh không bảo vệ. Dưới đây Bình đóng vai GitLab để bạn thấy kết quả trên lịch sử, rồi An dọn dẹp ở máy mình:','Once the reviewer is happy and the pipeline is green, someone with permission clicks <strong>Merge</strong>. Default rules according to the documentation: the default branch (usually <code>main</code>) is protected and only Maintainers and above can merge into it; Developers can merge MRs that target unprotected branches. Below Binh plays GitLab so you can see the result in history, then An cleans up locally:'))
    o+=T3+T4
    o+=p(t('Đồ thị cho thấy merge commit ghép nhánh <code>12-course-price</code> vào <code>main</code>, kèm hai commit của MR. Với thiết lập thật, GitLab còn cho chọn <em>squash</em> (gộp các commit của MR thành một) khi merge; bài 8 giải thích squash.','The graph shows a merge commit joining <code>12-course-price</code> into <code>main</code>, together with the MR\'s two commits. In a real setup GitLab also offers <em>squash</em> (combining the MR\'s commits into one) at merge time; part 8 explains squashing.'))
    o+=p(t('Một thói quen nhỏ nhưng giá trị: ngay sau khi MR của bạn được merge, hãy chuyển về <code>main</code>, <code>git pull</code> rồi mới tạo nhánh kế tiếp. Nếu bỏ qua, nhánh mới sẽ tách từ <code>main</code> cũ và MR sau dễ xung đột hoặc kéo theo commit đã merge. Tương tự, đừng để nhánh đã merge nằm lại: xóa cả bản cục bộ lẫn bản trên GitLab như ở bài 4.','A small habit with real value: right after your MR is merged, switch to <code>main</code>, run <code>git pull</code>, and only then create the next branch. If you skip it, the new branch starts from an old <code>main</code> and the next MR is likely to conflict or drag in already-merged commits. Likewise do not leave merged branches lying around: delete both the local and the GitLab copy as in part 4.'))
    o+=h2('approve',t('Approve, auto-merge và vai trò của từng gói GitLab','Approvals, auto-merge and what each GitLab tier gives you'))
    o+=p(t('Cách duyệt khác nhau tùy gói GitLab. Theo tài liệu, trên gói Free mọi người từ vai trò Developer trở lên đều có thể approve MR nhưng việc approve chỉ mang tính tùy chọn, không ngăn được merge. Gói Premium và Ultimate cho phép đặt <em>quy tắc bắt buộc</em>: số người duyệt tối thiểu, loại reviewer (backend, frontend, QA...) hoặc dùng file <code>CODEOWNERS</code> để chỉ định người duyệt theo từng thư mục; chưa đủ approval thì không merge được. Khi reviewer đã hài lòng mà pipeline vẫn đang chạy, họ có thể đặt MR ở chế độ <em>auto-merge</em>: khi mọi điều kiện đạt, GitLab tự merge mà bạn không phải làm gì thêm.','How review works depends on your GitLab tier. According to the documentation, on the Free tier anyone with the Developer role or higher can approve an MR but approvals are optional and do not prevent merging. Premium and Ultimate add <em>required rules</em>: a minimum number of approvers, kinds of reviewer (backend, frontend, QA...) or a <code>CODEOWNERS</code> file that names reviewers per folder; without enough approvals the MR cannot be merged. Once a reviewer is happy but the pipeline is still running, they can put the MR on <em>auto-merge</em>: once all checks pass GitLab merges it for you.'))
    o+=h2('bao-ve',t('Vì sao không push thẳng được vào main','Why you cannot push straight to main'))
    o+=p(t('Theo tài liệu GitLab, nhánh mặc định của repo được bảo vệ sẵn. Nhánh bảo vệ kiểm soát ai được merge và push, ngăn xóa nhầm và có thể bắt buộc review. Maintainer cấu hình ở <em>Settings → Repository → Branch rules</em>. Để bạn thấy hiệu ứng, ví dụ này dùng một hook trên “GitLab” giả để từ chối push vào <code>main</code>; thông báo <em>remote:</em> do chính ta viết, còn GitLab thật sẽ in lời nhắn của riêng nó, nhưng dòng cuối <em>remote rejected</em> thì giống nhau:','Per GitLab\'s documentation, a repository\'s default branch comes protected. A protected branch controls who may merge and push, prevents accidental deletion and can require review. Maintainers configure it under <em>Settings → Repository → Branch rules</em>. To show the effect, this example uses a hook on the simulated “GitLab” that refuses pushes to <code>main</code>; the <em>remote:</em> line is our own text, and real GitLab prints its own wording, but the final <em>remote rejected</em> line looks the same:'))
    o+=T5
    o+=p(t('Commit đã nằm trên <code>main</code> cục bộ. Cách xử lý chuẩn: giữ commit bằng cách tạo nhánh từ đây rồi push nhánh đó, sau đó đưa <code>main</code> cục bộ về lại đúng <code>origin/main</code> (lệnh <code>git reset --hard</code> sẽ được giải thích ở bài 7; hãy chắc chắn commit đã nằm an toàn trên nhánh mới trước khi chạy):','The commit is already on your local <code>main</code>. The standard fix: keep the commit by creating a branch from here and pushing that, then move local <code>main</code> back to exactly <code>origin/main</code> (the <code>git reset --hard</code> command is explained in part 7; make sure the commit is safe on the new branch before running it):'))
    o+=T5b
    o+=h2('mr-tot',t('Viết một merge request dễ duyệt','Writing a merge request that is easy to review'))
    o+=tbl([t('Nên','Do'),t('Vì sao','Why')],[
        [t('MR nhỏ, một mục đích','Small MRs with one purpose'),t('Reviewer đọc nhanh và bắt lỗi tốt hơn; dễ hoàn tác nếu cần','Reviewers read quickly and catch more; easy to undo if needed')],
        [t('Mô tả rõ lý do, thay đổi, cách kiểm tra','Describe the reason, changes and how to test'),t('Người duyệt không phải đoán bạn muốn gì','Reviewers do not have to guess your intent')],
        [t('Liên kết issue bằng <code>Closes #12</code>','Link the issue with <code>Closes #12</code>'),t('Theo tài liệu, các từ như Close/Closes, Fix/Fixes, Resolve/Resolves, Implement/Implements đứng trước tham chiếu issue sẽ tự đóng issue khi merge','According to the documentation, words such as Close/Closes, Fix/Fixes, Resolve/Resolves and Implement/Implements before an issue reference close it automatically on merge')],
        [t('Mở MR sớm','Open the MR early'),t('Tài liệu khuyên tạo MR sớm để nhóm có thời gian bắt lỗi; nếu chưa xong, báo rõ trong tiêu đề hoặc mô tả','The documentation recommends opening early giving the team room to spot bugs early; if unfinished, say so in the title or body')],
        [t('Tự đọc lại diff trước khi gửi','Re-read your own diff first'),t('Bắt được <code>print</code> quên xóa, file thừa, mật khẩu lỡ commit','Catches forgotten <code>print</code> calls, stray files and committed passwords')]])
    o+=h2('trong-odoo',t('Reviewer nhìn gì trong một MR của module Odoo','What a reviewer looks for in an Odoo module MR'))
    o+=ul([t('<strong>Quyền truy cập:</strong> model mới đã có dòng trong <code>ir.model.access.csv</code> chưa (bài 8 series Odoo).','<strong>Access rights:</strong> does a new model have a row in <code>ir.model.access.csv</code> (the access-rights part of the Odoo series).'),t('<strong>Manifest:</strong> file XML mới đã nằm trong <code>data</code> của <code>__manifest__.py</code> và đúng thứ tự phụ thuộc chưa.','<strong>Manifest:</strong> is the new XML file listed under <code>data</code> in <code>__manifest__.py</code>, in dependency order.'),t('<strong>Nâng cấp module:</strong> đã chạy <code>-u vinc_course</code> trên một CSDL thử và không báo lỗi chưa.','<strong>Module upgrade:</strong> was <code>-u vinc_course</code> run on a test database without errors.'),t('<strong>Phạm vi:</strong> MR có sửa nhầm module khác hoặc kéo theo file không liên quan không; Odoo cũng khuyên tránh một commit đụng nhiều module cùng lúc.','<strong>Scope:</strong> does the MR touch another module or unrelated files; Odoo\'s guidelines also advise against one commit changing several modules at once.'),t('<strong>Bí mật:</strong> không có mật khẩu, API key hay <code>odoo.conf</code> thật trong diff.','<strong>Secrets:</strong> no passwords, API keys or real <code>odoo.conf</code> in the diff.')])
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong>Push thẳng lên <code>main</code> bị chặn.</strong> Đừng cố ép. Tạo nhánh từ commit hiện tại, push nhánh đó và mở MR như ở phần trên.','<strong>A direct push to <code>main</code> is blocked.</strong> Do not try to force it. Create a branch from the current commit, push it and open an MR as above.'),
        t('<strong>Tạo MR mới mỗi lần sửa theo góp ý.</strong> Chỉ cần push thêm commit lên cùng nhánh; MR cũ tự cập nhật và giữ nguyên toàn bộ thảo luận.','<strong>Opening a new MR for every round of fixes.</strong> Just push more commits to the same branch; the existing MR updates itself and keeps the whole discussion.'),
        t('<strong>MR báo xung đột với nhánh đích.</strong> Có người đã sửa cùng dòng trên <code>main</code> trong lúc bạn làm. Hãy lấy <code>main</code> mới về nhánh của bạn và giải quyết xung đột ở máy (bài 6), rồi push lại.','<strong>The MR reports conflicts with the target branch.</strong> Someone changed the same lines on <code>main</code> while you worked. Bring the fresh <code>main</code> into your branch and resolve the conflicts locally (part 6), then push again.'),
        t('<strong>MR to như một dự án.</strong> Hàng chục file và nhiều mục đích khiến reviewer duyệt qua loa. Tách thành nhiều MR nối tiếp nhau; GitLab còn tự chuyển đích của MR phụ thuộc khi MR trước được merge.','<strong>An MR as big as a project.</strong> Dozens of files and several purposes make reviewers skim. Split it into chained MRs; GitLab even retargets a dependent MR when the previous one is merged.')])
    o+=h2('tong-ket',t('Tổng kết','Summary'))
    o+=ul([t('MR là cổng review: code chỉ vào nhánh chính sau khi có người xem và pipeline đạt.','An MR is the review gate: code reaches the main branch only after someone reads it and the pipeline passes.'),t('Quy trình: nhánh theo issue → commit → push → mở MR → sửa theo góp ý bằng commit mới → merge → dọn nhánh.','The flow: issue-based branch → commits → push → open MR → fix feedback with new commits → merge → clean up.'),t('<code>Closes #12</code> trong commit hoặc mô tả tự đóng issue khi merge.','<code>Closes #12</code> in a commit or description closes the issue on merge.'),t('Nhánh mặc định được bảo vệ: push thẳng bị từ chối, hãy đi qua MR.','The default branch is protected: direct pushes are refused, so go through an MR.')])
    o+=p(t('Khi hai MR cùng sửa một chỗ, bạn sẽ gặp <strong>xung đột</strong>. Đó là điều đáng sợ nhất với người mới, và cũng dễ hơn bạn nghĩ. Bài 6 hướng dẫn đọc các dấu <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>, sửa tay và hoàn tất merge.','When two MRs change the same place you meet a <strong>conflict</strong>. It is the scariest part for newcomers, and easier than you think. Part 6 shows how to read the <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code> markers, fix by hand and finish the merge.'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
